pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        vm.assume(receiver != address(0) && receiver != address(c));
        vm.assume(amount > 0 && amount <= address(c).balance);

        uint256 balanceBefore = address(c).balance;
        bool success;

        // Attempt call as owner
        vm.prank(address(this)); // owner is the deployer (this test contract)
        (success, ) = address(c).call(abi.encodeWithSelector(c.sendTo.selector, receiver, amount));

        if (success) {
            assertTrue(address(c).balance == balanceBefore - amount, "sendTo by owner should transfer amount");
        } else {
            assertTrue(address(c).balance == balanceBefore, "sendTo by non-owner should revert with no transfer");
        }
    }
}

