pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // Restrict to valid inputs per require conditions
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);

        uint256 receiverBalanceBefore = receiver.balance;
        uint256 contractBalanceBefore = address(c).balance;

        // Drive call
        c.sendTo(receiver, amount);

        // General rule: receiver balance increases by the exact amount sent
        uint256 receiverBalanceAfter = receiver.balance;
        uint256 contractBalanceAfter = address(c).balance;

        // Since owner sends from contract balance to receiver
        assertTrue(
            receiverBalanceAfter - receiverBalanceBefore == amount &&
            contractBalanceBefore - contractBalanceAfter == amount,
            "Receiver balance should increase by amount and contract balance should decrease by amount"
        );
    }
}

