pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address receiver, uint256 amount) public {
        // only consider valid calls: sender is owner, receiver nonzero, amount > 0
        vm.assume(receiver != address(0));
        vm.assume(amount > 0);
        vm.assume(amount <= address(this).balance); // enough ether to send

        // fund the owner (this contract) and record owner balance
        vm.deal(address(this), 1 ether); // arbitrary positive balance
        uint256 ownerBalanceBefore = address(this).balance;

        // call sendTo as owner
        c.sendTo(receiver, amount);

        uint256 ownerBalanceAfter = address(this).balance;
        // the owner should lose exactly the sent amount (in reference, actual amount; in bug, zero)
        assertTrue(ownerBalanceBefore - ownerBalanceAfter == amount, "Owner balance did not decrease by amount");
    }
}

